function pathAt(points,t){const lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));const total=lengths.reduce((a,b)=>a+b,0);let d=Math.min(.999999,Math.max(0,t))*total;for(let i=0;i<lengths.length;i++){if(d<=lengths[i])return[points[i][0]+(points[i+1][0]-points[i][0])*d/lengths[i],points[i][1]+(points[i+1][1]-points[i][1])*d/lengths[i]];d-=lengths[i];}return points.at(-1);}
