for(const [id,n]of Object.entries(N)){const active=id===current,hold=active&&blockedAt(state)===id&&!state.resolved,visited=highlight.includes(id);ctx.fillStyle=active?(hold?'#573a38':'#3b4a55'):visited?'#35414a':'#293238';ctx.fillRect(n.x,n.y,nodeW,nodeH);ctx.strokeStyle=active?(hold?colors.error:colors.orange):'#596872';ctx.lineWidth=active?2.5:1;ctx.strokeRect(n.x+.5,n.y+.5,nodeW-1,nodeH-1);ctx.font='16px Arial';ctx.textAlign='center';ctx.fillStyle=colors.text;ctx.fillText(n.title,n.x+80,n.y+27);ctx.font='12px Arial';ctx.fillStyle=hold?colors.error:colors.muted;ctx.fillText(hold?'AWAITING ACTION':n.sub,n.x+80,n.y+49);}
if(state.phase>0&&state.index<list.length-1){const p=pathAt(edgePath(current,list[state.index+1]),state.phase);ctx.fillStyle=colors.orange;ctx.beginPath();ctx.arc(p[0],p[1],6,0,Math.PI*2);ctx.fill();}
