let state={channel:'ecom',scenario:'normal',putaway:'reserve',index:0,phase:0,resolved:false,running:false},last=null,raf=0;
function hold(){return route(state)[state.index]===blockedAt(state)&&!state.resolved;}
function update(){const ids=route(state);state.index=Math.min(state.index,ids.length-1);const id=ids[state.index];get('stepNumber').textContent=String(state.index+1).padStart(2,'0');get('stepTitle').textContent=N[id].title;get('stepDetail').textContent=id==='release'&&state.scenario==='unslotted'?'The selected wave includes an order for an unslotted SKU. Assign a valid location before the wave can proceed. No wait time is assumed.':N[id].detail;const actions={manual:'Continue with manual unload',cubiscan:'Confirm dimensions captured',release:'Confirm location assigned',lane:'Confirm Lane 6 cleared',ira:'Confirm inventory reconciled'};get('resolve').hidden=!hold();get('resolve').textContent=actions[id]||'Continue';get('next').disabled=hold()||state.index===ids.length-1;get('play').disabled=hold()||state.index===ids.length-1;get('play').textContent=state.running?'Pause walkthrough':'Play walkthrough';if(ctx)draw(ctx,state);}
