get('play').addEventListener('click',()=>{state.running=!state.running;last=null;update();});get('next').addEventListener('click',()=>{state.running=false;advance();});get('reset').addEventListener('click',restart);get('resolve').addEventListener('click',()=>{state.resolved=true;advance();});
function tick(now){const dt=last===null?0:Math.min(100,now-last);last=now;if(state.running&&!document.hidden){state.phase+=dt/1200;if(state.phase>=1)advance();else if(ctx)draw(ctx,state);}raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);
